# Antiquity polity profiles, part 3: Balkans, steppe, Caucasus and Iran
from part2 import P, add

add(id="illyrians", name="Illyrians", type="tribal kingdoms", yearsActive="c. 1000–168 BC (independent)",
 summary="The Indo-European peoples of the western Balkans, from the Adriatic coast to the Morava valley, whose kingdoms fought Macedon and Rome until Rome conquered them in 168 BC.",
 description="Illyrian tribes such as the Taulantii, Ardiaei, Dalmatae and Dardani lived along the eastern Adriatic and inland. Bardylis built a kingdom that defeated Macedon before Philip II crushed it in 358 BC. In the third century BC the Ardiaean kingdom under Agron and Queen Teuta raided Adriatic shipping, which led to the Illyrian Wars with Rome. Rome captured King Gentius in 168 BC and crushed the Great Illyrian Revolt of AD 6–9.",
 conflicts="Wars with Macedon under Bardylis and Philip II; the First and Second Illyrian Wars with Rome (229–228, 220–219 BC); the Third (168 BC); the Batonian War (AD 6–9).",
 leaders="Bardylis, Glaucias (who sheltered the infant Pyrrhus), Agron, Queen Teuta and Gentius.",
 religion="Sun and serpent symbols appear on their metalwork, and the serpent was linked to the founding myth of Cadmus in Illyria.",
 culture="Hill-forts and coastal towns; Illyrian light ships, the lemboi, were copied by the Romans as the liburna.",
 literature="No writings survive; the Illyrian language is known only from names.",
 art="Silver belt buckles and jewellery from sites such as Gostilj and Selca e Poshtme.",
 ideas="Roman writers saw them as pirates; Illyricum later gave Rome many soldier-emperors, including Diocletian.",
 science="Their light, fast ships influenced Roman naval design.",
 story=[{"title":"Queen Teuta","text":"When Roman envoys came to complain about Illyrian piracy in 230 BC, Queen Teuta replied that it was not the custom of Illyrian kings to stop their subjects taking booty at sea. One envoy was murdered on the way home, and Rome declared war."}],
 sources="Encyclopaedia Britannica, 'Illyria'; J. Wilkes, The Illyrians (1992).",
 images=[("Byllis Albania","Ruins of Byllis in southern Albania","culture")])

add(id="thracians", name="Thracians", type="tribal kingdoms", yearsActive="c. 1000 BC–AD 46",
 nameByTick={"-1": "Odrysian Kingdom"},
 summary="The many Thracian tribes of the eastern Balkans, between the Danube and the Aegean, united at times by the Odrysian kings until Rome annexed Thrace in AD 46.",
 description="Herodotus called the Thracians the most numerous people after the Indians. They were divided among tribes such as the Odrysae, Getae, Triballi and Bessi. The Odrysian kingdom, founded by Teres around 480 BC after the Persian retreat, became the largest state in the eastern Balkans. Philip II and Alexander conquered much of Thrace, but Odrysian kings survived and later ruled as Roman clients until Claudius made Thrace a province in AD 46.",
 conflicts="Wars with Macedon under Philip II; Lysimachus's kingdom in Thrace (from 323 BC); the Celtic kingdom of Tylis (third century BC); Roman wars against the Bessi.",
 leaders="Teres I and Sitalces of the Odrysae; Seuthes III, whose capital Seuthopolis has been excavated; Rhoemetalces I, a Roman client.",
 religion="The cult of Zalmoxis among the Getae, the Thracian Rider hero and Orphic mysteries said to come from Thrace.",
 culture="Aristocrats were buried in tumuli with gold treasures; Thracian peltasts (light infantry) served in Greek armies.",
 literature="Orpheus was said to be a Thracian; the Thracian language survives only in a few inscriptions.",
 art="The Kazanlak and Sveshtari tombs are UNESCO World Heritage sites, and the Panagyurishte gold treasure is world-famous.",
 ideas="The Getae's belief in immortality impressed Herodotus.",
 science="Thracian gold and silver work was among the finest of the ancient world.",
 story=[{"title":"Spartacus","text":"Spartacus, the gladiator who led the great slave revolt of 73–71 BC, was a Thracian. His army of tens of thousands of escaped slaves defeated several Roman armies before Crassus crushed it."}],
 sources="Encyclopaedia Britannica, 'Thrace', 'Odrysian kingdom'; Z. Archibald, The Odrysian Kingdom of Thrace (1998).",
 images=[("Kazanlak Thracian Tomb fresco","Fresco in the Thracian tomb at Kazanlak (4th century BC)","art"),
         ("Panagyurishte treasure","The Panagyurishte gold treasure","culture")])

add(id="dacians", name="Dacia", type="kingdom", yearsActive="c. 82 BC–AD 106",
 summary="The kingdom of the Dacians and Getae north of the lower Danube, united by Burebista and later by Decebalus, conquered by Trajan in AD 106.",
 description="The Dacians and Getae were Thracian-speaking peoples in what is now Romania. Around 82 BC Burebista united them into a powerful kingdom that stretched from the Black Sea to Slovakia. It split after his death in 44 BC but was reunited under Decebalus, who defeated a Roman army in AD 86. Trajan conquered Dacia in two wars (101–102 and 105–106), and its gold made the province rich until Rome abandoned it around 271.",
 conflicts="Burebista's wars against the Celtic Boii and the Greek cities of the Black Sea; Domitian's Dacian war (85–89); Trajan's two Dacian Wars.",
 leaders="Burebista (c. 82–44 BC), the high priest Deceneus and Decebalus (87–106).",
 religion="The god Zalmoxis promised immortality; sanctuaries at Sarmizegetusa include a circular stone sanctuary often interpreted as a calendar.",
 culture="Fortified citadels in the Orăștie mountains, with Sarmizegetusa Regia as the royal and religious capital.",
 literature="Dacian was unwritten; Trajan's lost Commentaries on the war are known only from a fragment.",
 art="Trajan's Column in Rome shows the wars in a spiral relief; Dacian silver jewellery and the dragon standard (draco) survive.",
 ideas="Dacian priests combined religious and political authority, as Deceneus did under Burebista.",
 science="Dacian builders used a distinctive cut-stone wall technique (murus dacicus).",
 story=[{"title":"The last of Decebalus","text":"As Roman cavalry closed in on him in AD 106, Decebalus cut his own throat rather than be paraded in Trajan's triumph. A Roman officer, Tiberius Claudius Maximus, brought his head to Trajan, and his tombstone records the deed."}],
 sources="Encyclopaedia Britannica, 'Dacia'; Cassius Dio, Roman History book 68.",
 images=[("Sarmizegetusa Regia","The sanctuary terrace at Sarmizegetusa Regia","culture"),
         ("Trajan's Column Decebalus","Trajan's Column relief of the death of Decebalus","art")])

add(id="scythians", name="Scythians", type="nomadic kingdom", yearsActive="c. 7th century BC–AD 3rd century",
 summary="The Iranian-speaking nomads of the Pontic steppe, famous as mounted archers and for their gold-filled kurgans, whose last kingdom survived in Crimea into the Roman era.",
 description="Scythians dominated the steppe north of the Black Sea from the seventh century BC. Herodotus describes Royal Scythians ruling over farming and nomad tribes, and their defeat of Darius I by retreating into the steppe. In the fourth century BC King Ateas ruled from the Danube to the Don before dying in battle against Philip II. Pressed by the Sarmatians, Scythians retreated to Crimea and the Dobruja, where a Late Scythian kingdom with its capital at Neapolis survived until the Goths arrived.",
 conflicts="Raids into the Near East in the seventh century BC; Darius I's failed invasion (c. 513 BC); war with Philip II (339 BC); conflicts with the Bosporan Kingdom and Chersonesus.",
 leaders="Idanthyrsus, who defied Darius; Ateas (died 339 BC); Skilurus, king in Crimea in the second century BC.",
 religion="Herodotus reports worship of the hearth goddess Tabiti and a war god whose shrine was a sword set on a pile of brushwood.",
 culture="Nomads living in wagons and following their herds; nobles were buried with horses, servants and gold.",
 literature="No Scythian writing; Herodotus's fourth book is the main ancient account.",
 art="The 'animal style' gold work, such as the Solokha comb and the Tovsta Mohyla pectoral.",
 ideas="Greek writers saw the Scythians both as savages and as wise 'noble barbarians', like the sage Anacharsis.",
 science="The Scythians were masters of horse archery with the composite bow; Herodotus describes them inhaling hemp smoke in tents.",
 story=[{"title":"A strange gift","text":"When Darius invaded, the Scythians sent him a bird, a mouse, a frog and five arrows. One Persian adviser explained: unless you fly like birds, hide like mice or leap into lakes like frogs, you will die by our arrows."}],
 sources="Encyclopaedia Britannica, 'Scythian'; R. Rolle, The World of the Scythians (1989); Herodotus, Histories book 4.",
 images=[("Scythian pectoral Tovsta Mohyla","Gold pectoral from the Tovsta Mohyla kurgan (4th century BC)","art"),
         ("Solokha comb","Gold comb from the Solokha kurgan showing Scythian warriors","culture")])

add(id="sarmatians", name="Sarmatians", type="nomadic confederation", yearsActive="c. 4th century BC–AD 4th century",
 nameByTick={"100": "Sarmatians and Alans", "300": "Sarmatians and Alans"},
 summary="The Iranian-speaking nomads who replaced the Scythians on the Pontic steppe, including the Roxolani, Iazyges and Alans, heavily armoured horsemen who fought and served Rome.",
 description="The Sarmatians moved west from the Volga and Ural steppe from the fourth century BC and dominated the region between the Don and the Danube by the first century BC. The Iazyges settled the Hungarian plain between Roman Pannonia and Dacia, and the Roxolani raided across the lower Danube. Marcus Aurelius defeated the Iazyges and sent 5,500 of their horsemen to serve in Britain in 175. In the first century AD the Alans became dominant in the east; the Huns broke them around 370, and some Alans went west with the Vandals.",
 conflicts="Raids on Roman Moesia; the Marcomannic Wars (166–180), with the Iazyges allied to the Germans; wars with the Goths in the third century.",
 leaders="Zanticus of the Iazyges, who made peace with Marcus Aurelius; Rasparaganus, a Roxolanian king who took Roman citizenship.",
 religion="Ammianus says the Alans worshipped a naked sword stuck in the ground as their war god.",
 culture="Some women were buried with weapons; cataphracts (armoured horsemen) with long lances were their elite.",
 literature="Unwritten; the modern Ossetian language descends from Alanic.",
 art="Polychrome gold jewellery with garnets and turquoise, as in the Khokhlach kurgan treasure.",
 ideas="Herodotus linked them to the Amazons, and the legend may echo Sarmatian women fighters.",
 science="Scale armour for horse and rider and the long lance (kontos) influenced Roman cavalry.",
 story=[{"title":"Sarmatians in Britain","text":"After 175, thousands of Iazyges horsemen were stationed in northern Britain, some at Ribchester in Lancashire. Some historians have suggested that their dragon banners and sword cult influenced the Arthurian legends."}],
 sources="Encyclopaedia Britannica, 'Sarmatian', 'Alani'; T. Sulimirski, The Sarmatians (1970).",
 images=[("Sarmatian cataphracts Trajan's Column","Sarmatian armoured cavalry on Trajan's Column","culture")])

add(id="armenia", name="Kingdom of Armenia", type="kingdom", yearsActive="c. 331 BC–AD 428",
 summary="The kingdom of the Armenian highlands, ruled by the Orontid, Artaxiad and Arsacid dynasties, a buffer between Rome and Iran and the first state to adopt Christianity, around 301.",
 description="After Alexander's conquest Armenia was ruled by the Orontid dynasty as a semi-independent satrapy. Artaxias I founded a new dynasty in 189 BC, and Tigranes the Great (95–55 BC) built a short-lived empire from the Caspian to Syria before submitting to Pompey. From AD 66 a branch of the Parthian Arsacids ruled Armenia under Roman crowning. Around 301 King Tiridates III was converted by Gregory the Illuminator and made Christianity the state religion.",
 conflicts="Tigranes's wars with Parthia and Rome, including Lucullus's victory at Tigranocerta (69 BC); the Roman–Parthian war over Armenia ended by the settlement of Rhandeia (AD 63).",
 leaders="Orontes, Artaxias I, Tigranes the Great, Tiridates I (crowned by Nero in Rome in 66) and Tiridates III.",
 religion="Worship of Aramazd and Anahit, influenced by Zoroastrianism, until the conversion; the Armenian Apostolic Church traces itself to Gregory the Illuminator.",
 culture="Artashat and Tigranocerta were royal capitals; the Garni temple is the only standing Greco-Roman colonnaded temple in the former Soviet Union.",
 literature="Greek was used at the court of Tigranes, whose son Artavasdes II wrote Greek tragedies; the Armenian alphabet was invented by Mesrop Mashtots around 405.",
 art="The Ionic temple of Garni (1st century AD) and royal coins of Tigranes in the Armenian tiara.",
 ideas="Armenia's position between Rome and Iran made it the classic contested buffer state.",
 science="Armenian highland agriculture and metallurgy were long established.",
 story=[{"title":"A crown in Rome","text":"In AD 66 the Parthian prince Tiridates travelled to Rome to receive the Armenian crown from Nero. The emperor closed the doors of the temple of Janus to mark peace, and the visit was celebrated with lavish games."}],
 sources="Encyclopaedia Britannica, 'Armenia: History'; R. G. Hovannisian (ed.), The Armenian People from Ancient to Modern Times vol. 1 (1997).",
 images=[("Garni Temple","The temple of Garni (1st century AD)","art"),
         ("Tigranes the Great coin","Coin portrait of Tigranes the Great in the Armenian tiara","leader")])

add(id="atropatene", name="Atropatene", type="kingdom", yearsActive="c. 323 BC–3rd century AD",
 summary="The kingdom of Media Atropatene in what is now Iranian Azerbaijan, founded by the Persian satrap Atropates after Alexander's death.",
 description="Atropates, Persian satrap of Media, kept his northern province as an independent kingdom after Alexander's death in 323 BC, and his dynasty ruled it for generations. It later became a vassal of the Parthians and was absorbed by the Sasanians in the third century AD. The region's name survives in 'Azerbaijan'.",
 conflicts="Wars with the Seleucids; Mark Antony's failed siege of its capital Phraaspa in 36 BC.",
 leaders="Atropates, the founder; Artavasdes I, who later allied with Mark Antony.",
 religion="It was a centre of Zoroastrianism; the fire temple of Adur Gushnasp at Takht-e Soleyman was later one of the three great fires of Iran.",
 culture="Persian and Median aristocratic traditions continued here after the fall of the Achaemenids.",
 literature="Known mainly from Greek and Roman writers such as Strabo and Plutarch.",
 art="The later Sasanian site of Takht-e Soleyman stands beside the region's sacred lake.",
 ideas="Iranian kingship and religion survived here outside Greek rule.",
 science="Highland agriculture and horse breeding.",
 story=[{"title":"Antony's retreat","text":"In 36 BC Mark Antony besieged Phraaspa, the capital of Atropatene, but the Parthians destroyed his siege train. His retreat through the mountains in winter cost him a large part of his army."}],
 sources="Encyclopaedia Britannica, 'Atropatene'; Encyclopaedia Iranica, 'Atropates'; Plutarch, Life of Antony.",
 images=[("Takht-e Soleyman","Takht-e Soleyman, the sacred fire site of Atropatene","culture")])

add(id="colchis", name="Colchis", type="kingdom", yearsActive="c. 6th–1st century BC",
 summary="The kingdom on the eastern shore of the Black Sea, in western Georgia, which the Greeks knew as the land of the Golden Fleece.",
 description="Colchis was home to Kartvelian-speaking peoples who traded with Greek colonies such as Phasis and Dioscurias. It was famous for gold, linen and timber. It came under Mithridates VI of Pontus in the late second century BC and then under Roman influence after Pompey's campaign of 65 BC.",
 conflicts="Its rulers fought neighbouring tribes and later came under Pontus and then Rome.",
 leaders="Kings such as Saulaces and Akes are known from coins and Greek writers.",
 religion="Local gods alongside Greek cults in the colonies.",
 culture="Greek colonists and local peoples mixed in its coastal towns.",
 literature="The Greek myth of Jason, Medea and the Golden Fleece, told by Apollonius of Rhodes.",
 art="Gold jewellery from Vani, a city sanctuary in Colchis, shows fine local craftsmanship.",
 ideas="The myth of the Golden Fleece may reflect the practice of collecting gold dust from rivers with sheepskins.",
 science="Colchian gold-washing and linen weaving were famous in antiquity.",
 story=[{"title":"The Golden Fleece","text":"Greek myth said Jason and the Argonauts sailed to Colchis to take the golden fleece of a magic ram, helped by the king's daughter Medea. Strabo explains that locals caught gold dust from streams in sheepskins."}],
 sources="Encyclopaedia Britannica, 'Colchis'; D. Braund, Georgia in Antiquity (1994).",
 images=[("Vani gold Colchis","Colchian gold jewellery from Vani","art")])

add(id="parthia", name="Parthian Empire", type="empire", yearsActive="c. 247 BC–AD 224",
 summary="The Iranian empire of the Arsacid dynasty, which took Iran and Mesopotamia from the Seleucids and was Rome's great rival in the east for nearly three centuries.",
 description="The Parni nomads under Arsaces I took the Seleucid province of Parthia around 247 BC. Mithridates I (c. 171–132 BC) conquered Media and Mesopotamia, and Ctesiphon on the Tigris became a capital. Parthia destroyed Crassus's army at Carrhae in 53 BC and fought Rome for control of Armenia and Mesopotamia. Weakened by Roman invasions and civil wars, it was overthrown by the Persian Ardashir I in 224.",
 conflicts="Carrhae (53 BC); Mark Antony's failed invasion (36 BC); Trajan's conquest of Mesopotamia (115–117); the Roman sacks of Ctesiphon under Lucius Verus and Septimius Severus.",
 leaders="Arsaces I, Mithridates I, Mithridates II and Artabanus IV, the last king.",
 religion="Zoroastrianism alongside Greek, Babylonian and Jewish communities; the Parthians were tolerant overlords.",
 culture="A decentralised empire of great noble houses; Greek cities kept their institutions under Parthian rule.",
 literature="Parthian minstrels (gosans) carried oral epics; Greek remained in use on coins.",
 art="The bronze statue of a Parthian nobleman from Shami and the frontal style of Palmyra and Hatra.",
 ideas="The kings called themselves 'philhellenes' on their coins while reviving Iranian traditions.",
 science="The 'Parthian shot', firing backwards from a galloping horse, became proverbial.",
 story=[{"title":"Crassus's head","text":"After Carrhae, the head of Crassus, richest man in Rome, was sent to the Parthian king. Plutarch says it arrived during a performance of Euripides' Bacchae and was used as a prop in the final scene."}],
 sources="Encyclopaedia Britannica, 'Parthia'; Plutarch, Life of Crassus; M. Brosius, The Persians (2006).",
 images=[("Shami statue Parthian prince","Bronze statue of a Parthian nobleman from Shami","art"),
         ("Mithridates II drachm","Silver drachm of Mithridates II of Parthia","leader")])

add(id="sasanian", name="Sasanian Persia", type="empire", yearsActive="224–651",
 summary="The second Persian empire, founded by Ardashir I, which overthrew Parthia in 224 and fought Rome for four centuries.",
 description="Ardashir I, a Persian prince from Fars, defeated the last Parthian king in 224 and founded a more centralised empire with Zoroastrianism as its state religion. His son Shapur I captured the Roman emperor Valerian near Edessa in 260. Around 300 the Sasanians had just lost a war with Galerius and ceded territory on the upper Tigris by the Peace of Nisibis (299).",
 conflicts="Shapur I's victories over Gordian III, Philip the Arab and Valerian; Galerius's victory in 298 and the Peace of Nisibis.",
 leaders="Ardashir I (224–242), Shapur I (240–270) and Narseh (293–302).",
 religion="Zoroastrianism, organised under the high priest Kartir; the prophet Mani founded Manichaeism under Shapur I and was executed around 276.",
 culture="The king of kings ruled from Ctesiphon over noble families and a priestly hierarchy.",
 literature="Middle Persian royal inscriptions such as Shapur's at Naqsh-e Rostam.",
 art="Rock reliefs of royal victories, such as Valerian kneeling before Shapur at Naqsh-e Rostam, and silver plates with hunting scenes.",
 ideas="The ideal of the just king and the alliance of throne and fire temple.",
 science="Gondishapur became a centre of medicine and learning.",
 story=[{"title":"An emperor captured","text":"In 260 Shapur I captured the emperor Valerian. Roman Christian writers later claimed that Shapur used him as a footstool to mount his horse; Shapur's own reliefs show a Roman emperor kneeling before him."}],
 sources="Encyclopaedia Britannica, 'Sasanian dynasty'; T. Daryaee, Sasanian Persia (2009).",
 images=[("Naqsh-e Rostam Shapur Valerian relief","Relief of Shapur I's triumph over Roman emperors at Naqsh-e Rostam","art")])
